import json, numpy as np, itertools
rows=[json.loads(l) for l in open("examples.jsonl")]
D={s:np.array([[r['a'],r['b'],r['answer']] for r in rows if r['skill']==s]) for s in range(4)}
for s,d in D.items():
    print("skill",s,"class counts",np.bincount(d[:,2],minlength=8))
    a,b,y=d.T
    best=[]
    for m in list(range(2,33))+[63,64]:
        for p in range(0,m):
            for q in range(0,m):
                base=(p*a+q*b)%m
                # constant offset then mod 8 and raw
                for name,val in (("%8",base%8),):
                    for c in range(8):
                        acc=((val+c)%8==y).mean()
                        best.append((acc,f"({p}a+{q}b)%{m}{name}+{c}"))
    best.sort(key=lambda t:-t[0]); print(best[:4])
