No single simple formula fits (best near 0.34 with chance-level multiple testing); next I test for dependence on a or b alone, additive table structure, and two-branch rules against a shuffled-answer null.
```python
import json, numpy as np
rows=[json.loads(l) for l in open("examples.jsonl")]
D={s:np.array([[r['a'],r['b'],r['answer']] for r in rows if r['skill']==s]) for s in range(4)}
rng=np.random.default_rng(0)
def mi(x,y,nx=32):
    J=np.zeros((nx,8))
    for i,j in zip(x,y): J[i,j]+=1
    J/=J.sum(); px=J.sum(1,keepdims=True); py=J.sum(0,keepdims=True)
    m=J>0
    return (J[m]*np.log(J[m]/(px@py)[m])).sum()
for s,d in D.items():
    a,b,y=d.T
    for nm,x in (("a",a),("b",b),("a+b%8",(a+b)%8),("a-b%8",(a-b)%8),("a^b%8",(a^b)%8)):
        nx=32 if nm in "ab" else 8
        v=mi(x,y,nx); null=[mi(x,rng.permutation(y),nx) for _ in range(300)]
        print(s,nm,round(v,3),"null",round(np.mean(null),3),"p",np.mean(np.array(null)>=v))
# additive-table consistency over Z8 and XOR through independent cycles of the a-b bipartite graph
def cyc(d,op):
    a,b,y=d.T
    parent={};val={};ok=bad=0
    def find(n):
        path=0
        while parent[n]!=n:
            pass
    pot={}
    adj={}
    for i,(p,q,r) in enumerate(d):
        adj.setdefault(("a",p),[]).append((("b",q),r)); adj.setdefault(("b",q),[]).append((("a",p),r))
    for start in adj:
        if start in pot: continue
        pot[start]=0; st=[start]
        while st:
            u=st.pop()
            for v,r in adj[u]:
                exp=(r-pot[u])%8 if op=="add" else r^pot[u]
                if v not in pot: pot[v]=exp; st.append(v)
                elif pot[v]!=exp: bad+=1
                else: ok+=1
    return ok//2,bad//2
for s,d in D.items():
    print("skill",s,"add ok/bad",cyc(d,"add"),"xor ok/bad",cyc(d,"xor"))
