        m=fn(a,b)
        if m.sum()<12 or (~m).sum()<12: continue
        pred=(P[:,0,None]*a+P[:,1,None]*b+P[:,2,None])%8
        hit=(pred==y)
        s1=hit[:,m].sum(1); s2=hit[:,~m].sum(1)
        out.append(((s1.max()+s2.max())/len(y),nm,tuple(P[s1.argmax()]),tuple(P[s2.argmax()])))
    return max(out,key=lambda t:t[0])
